"use client";

import manifest from "./image-manifest.json";

const variants = manifest as Record<string, number[]>;

/**
 * next/image loader that points at the WebP files pre-generated by
 * scripts/generate-images.mjs. Picks the smallest generated width that is at
 * least the requested width (or the largest available).
 */
export default function imageLoader({ src, width }: { src: string; width: number; quality?: number }) {
  // Static imports resolve to /_next/static/media/<name>.<hash>.<ext>.
  const name = src.split("?")[0].split("/").pop() ?? "";
  const base = name.split(".")[0];
  const widths = variants[base];
  if (!widths) return src;
  const chosen = widths.find((w) => w >= width) ?? widths[widths.length - 1];
  return `/img/${base}-${chosen}.webp`;
}
